import csv
import io
from typing import Any


def parse_csv(raw_csv: str) -> dict[str, Any]:
    expected_width = 10

    try:
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False))
    except csv.Error:
        records = []

    header_index = None
    for index, record in enumerate(records):
        if len(record) == expected_width and any(value.strip() for value in record):
            header_index = index
            break

    if header_index is None:
        columns = [f"Column {index + 1}" for index in range(expected_width)]
        data_records = records
    else:
        columns = list(records[header_index])
        data_records = records[header_index + 1:]

    width = max([expected_width, len(columns)] + [len(record) for record in data_records])
    columns.extend(f"Column {index + 1}" for index in range(len(columns), width))

    rows = []
    for record in data_records:
        row = list(record)
        row.extend("" for _ in range(width - len(row)))
        rows.append(row)

    return {"columns": columns, "rows": rows}
